export function useLanguage() {
  const language = useState<AppLanguage>('app-language', () => 'en')
  const syncDocumentLocale = (value: AppLanguage) => {
    document.documentElement.lang = value
    document.documentElement.dir = value === 'ar' || value === 'ur' ? 'rtl' : 'ltr'
  }

  onMounted(() => {
    const saved = localStorage.getItem('app-language')
    if (supportedLanguages.some(option => option.value === saved)) language.value = saved as AppLanguage
    syncDocumentLocale(language.value)
  })

  const setLanguage = (value: AppLanguage) => {
    language.value = value
    localStorage.setItem('app-language', value)
    syncDocumentLocale(value)
  }

  const t = (key: LanguageKey): string => additionalMessages[language.value]?.[key] ?? messages[language.value === 'ru' ? 'ru' : 'en'][key]

  return { language, setLanguage, t }
}
